Suppose that $\mathcal{G} = \rho+\mathcal{G}_{\mathcal{H}} $ satisfies Assumption~3.2. Fix a failure probability $\delta\in(0,1)$, regularization strength $\lambda\in(0,1)$, and sample size $N$. Let ${\{\theta_m\}}\sim\mu^{\otimes M}$ be the $M$ random feature parameters and $\{(u_n,y_n)\}\sim\mathcal{P}^{\otimes N}$ be the data according to Assumption~3.3. For $\Phi$ the RFM~(2.1) satisfying Assumption~3.1, let $\widehat{\alpha}
    \in \mathbb{R}^M$ be the minimizer of the regularized $Y$-empirical risk $\mathscr{R}_N^\lambda({\,\cdot\,};Y)$ given by (2.3). If $M \ge \lambda^{-1}\log(32/\delta)$ and $N\geq \lambda^{-2}\log(16/\delta)$, then
    \begin{equation}
        \operatorname{\mathbb{E}}_{u\sim\nu}\left\lVert \mathcal{G}(u)-\Phi(u;\widehat{\alpha},{\{\theta_m\}}) \right\rVert_{\mathcal{Y}}^2  \leq 79e^{3/2}\bigl(\left\lVert \mathcal{G} \right\rVert_{L^\infty_\nu}^2 + 2\beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\lambda
    \end{equation}
    with probability at least $1-\delta$, where
    \begin{equation}
        \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta) \coloneqq 328 \left\lVert \mathcal{G}_{\mathcal{H}} \right\rVert_{\mathcal{H}}^2
            + 2023e^{3}\left\lVert \eta \right\rVert_{\psi_1(\mathcal{Y})}^2 + 8\lambda^{-1}\operatorname{\mathbb{E}}_{u\sim\nu}\left\lVert \rho(u) \right\rVert_{\mathcal{Y}}^2   + 18\lambda \left\lVert \rho \right\rVert_{L^\infty_\nu}^2
    \end{equation}
    is a function of $\rho$, $\lambda$, $\mathcal{G}_{\mathcal{H}}$, and the law of the noise variable $\eta$.

Let Assumptions 3.1 and 3.3 hold. Suppose that $\mathcal{G} = \rho+\mathcal{G}_{\mathcal{H}} $ satisfies Assumption~3.2. Fix $\delta\in(0,1)$, $\lambda\in(0,1)$, $M\in\mathbb{N}$, and $N\in\mathbb{N}$. Let $\widehat{\alpha}\in \mathbb{R}^M$ be the minimizer of the regularized $Y$-empirical risk $\mathscr{R}_N^\lambda({\,\cdot\,};Y)$ given by (2.3). If $M \ge \lambda^{-1}\log(16/\delta)$ and $N\geq \lambda^{-2}\log(8/\delta)$, then
\begin{equation}
    \mathscr{R}_N^\lambda(\widehat{\alpha};\mathcal{G}) \leq \lambda \beta(\rho,\lambda, \mathcal{G}_{\mathcal{H}}, \eta)
\end{equation}
with probability at least $1-\delta$, where the multiplicative factor $\beta(\rho,\lambda, \mathcal{G}_{\mathcal{H}}, \eta)$ is given by (3.3).

Let Assumption 3.1 hold. Suppose $\mathcal{G}$ satisfies Assumption~3.2. Let ${\{\theta_m\}}\sim\mu^{\otimes M}$ for the RFM $\Phi$ given by (2.1). Fix $\delta\in(0,1)$. For iid input samples ${\{u_n\}}\sim\nu^{\otimes N}$, define the random variable
    \begin{equation}
        \mathcal{E}_\beta\bigl({\{u_n\}},{\{\theta_m\}}\bigr)
        \coloneqq \sup_{\alpha\in\mathcal{A}_\beta}\left\lvert \frac{1}{N}\sum_{n=1}^N\left\lVert \mathcal{G}(u_n)-\Phi(u_n;\alpha) \right\rVert_{\mathcal{Y}}^2 - \operatorname{\mathbb{E}}_{u}\left\lVert \mathcal{G}(u)-\Phi(u;\alpha) \right\rVert_{\mathcal{Y}}^2 \right\rvert\,,
    \end{equation}
    where $\mathcal{A}_\beta\coloneqq \{\alpha'\in\mathbb{R}^M\, \vert \,  \left\lVert \alpha' \right\rVert_M^2\leq \beta\}$ and the deterministic radius $\beta=\beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)$ is given in (3.3) with $\mathcal{G}$ as above. If $N\geq \log(1/\delta)$, then with probability at least $1-\delta$ it holds that
    \begin{equation}
        \mathcal{E}_\beta\bigl({\{u_n\}},{\{\theta_m\}}\bigr) \leq 32e^{3/2}\bigl(\left\lVert \mathcal{G} \right\rVert_{L_\nu^\infty}^2 + \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\sqrt{\frac{6\log(2/\delta)}{N}}\,.
    \end{equation}

Let Assumptions 3.1 and 3.3 hold. Suppose that $\mathcal{G} = \rho+\mathcal{G}_{\mathcal{H}} $ satisfies Assumption~3.2. Fix $\delta\in(0,1)$, $\lambda\in(0,1)$, $M\in\mathbb{N}$, and $N\in\mathbb{N}$. Let $\widehat{\alpha}\in \mathbb{R}^M$ be the minimizer of the regularized $Y$-empirical risk $\mathscr{R}_N^\lambda({\,\cdot\,};Y)$ given by (2.3). If $M \ge \lambda^{-1}\log(16/\delta)$ and $N\geq \lambda^{-2}\log(8/\delta)$, then
\begin{equation}
    \mathscr{R}_N^\lambda(\widehat{\alpha};\mathcal{G}) \leq \lambda \beta(\rho,\lambda, \mathcal{G}_{\mathcal{H}}, \eta)
\end{equation}
with probability at least $1-\delta$, where the multiplicative factor $\beta(\rho,\lambda, \mathcal{G}_{\mathcal{H}}, \eta)$ is given by (3.3).

Suppose that $\mathcal{G}_{\mathcal{H}}\coloneqq \mathcal{G}\in \mathcal{H}$. Fix $\delta\in(0,1)$, $\lambda>0$, $N\in\mathbb{N}$, and $M\in\mathbb{N}$. Let ${\{\theta_m\}}\sim\mu^{\otimes M}$ and ${\{u_n\}}\sim\nu^{\otimes N}$. Define $\alpha^{\star} \in \mathbb{R}^M$ componentwise by
\begin{equation}
    \alpha^{\star}_m\coloneqq \alpha_{\mathcal{H}}(\theta_m)\mathds{1}_{\{\left\lvert \alpha_{\mathcal{H}}(\theta_m) \right\rvert\leq T\}}\,,\quad\text{where}\quad T \coloneqq \sqrt{\lambda^{-1}\operatorname{\mathbb{E}}_{\theta\sim\mu}|\alpha_{\mathcal{H}}(\theta)|^2}
\end{equation}
and
$\mathcal{G}_{\mathcal{H}}=\operatorname{\mathbb{E}}_{\theta\sim\mu}[\alpha_{\mathcal{H}}(\theta)\varphi({\,\cdot\,};\theta)]$ with $\left\lVert \mathcal{G}_{\mathcal{H}} \right\rVert_{\mathcal{H}}^2=\operatorname{\mathbb{E}}_{\theta\sim\mu}\left\lvert \alpha_{\mathcal{H}}(\theta) \right\rvert^2$.
If $M \ge \lambda^{-1}\log(4/\delta)$, then with probability at least $ 1-\delta$ in the random feature parameters $\theta_1,\dots, \theta_M$, it holds that
\begin{equation}
    \mathscr{R}_N^\lambda(\alpha^{\star};\mathcal{G}_{\mathcal{H}}) \le 81 \lambda \Vert \mathcal{G}_{\mathcal{H}} \Vert_{\mathcal{H}}^2.
\end{equation}

Let $\rho$ be as in Assumption~3.2. Fix $\delta\in(0,1)$. With probability at least $1-\delta$, it holds that
    \begin{equation}
        \frac{2}{N}\sum_{n=1}^N\left\lVert \rho(u_n) \right\rVert_{\mathcal{Y}}^2 \leq 4 \operatorname{\mathbb{E}}_{u\sim\nu} \left\lVert \rho(u) \right\rVert_{\mathcal{Y}}^2 + \frac{9\left\lVert \rho \right\rVert_{L^\infty_\nu}^2\log(2/\delta)}{N}\,.
    \end{equation}

Let Assumptions 3.1 and 3.3 hold. Fix $\alpha\in\mathbb{R}^M$, ${\{\theta_m\}}\sim\mu^{\otimes M}$, and $\delta\in(0,1)$. With probability at least $1-\delta$, it holds that
    \begin{equation}
        \frac{2}{N}\sum_{n=1}^N\left\langle -\eta_n, \Phi(u_n;\alpha) \right\rangle_{\mathcal{Y}}\leq 16e^{3/2}\left\lVert \eta_1 \right\rVert_{\psi_1(\mathcal{Y})}\left\lVert \alpha \right\rVert_M \sqrt{\frac{\log(2/\delta)}{N}}\,.
    \end{equation}

Fix $t>0$ and $\delta\in(0,1)$. Define
    \begin{equation}
        Z_t\coloneqq \sup_{\alpha\in\mathcal{A}_t}\left\lvert \frac{1}{N}\sum_{n=1}^N\left\langle \eta_n, \Phi(u_n;\alpha) \right\rangle_{\mathcal{Y}} \right\rvert\,,\quad\text{where}\quad \mathcal{A}_t\coloneqq {\left\{ \alpha\in\mathbb{R}^M \,\middle|\, \left\lVert \alpha \right\rVert_M^2\leq t \right\}}\,.
    \end{equation}
    If $N\geq\log(1/\delta)$, then conditioned on the realizations ${\{\theta_m\}}$ in the family $\Phi$ it holds that
    \begin{equation}
        Z_t\leq \operatorname{\mathbb{E}}_{\{(u_n,\eta_n)\}} [Z_t] + 8e^{3/2}\left\lVert \eta_1 \right\rVert_{\psi_1(\mathcal{Y})}\left\lVert \varphi \right\rVert_{L^\infty}\sqrt{\frac{\log(1/\delta)}{N}}\sqrt{t}
    \end{equation}
    with probability at least $1-\delta$.

Fix $t>0$. Define $\mathcal{A}_t$ as in Lem.~D.4. Then
    \begin{equation}
        \operatorname{\mathbb{E}}_{\{(u_n,\eta_n)\}} \sup_{\alpha\in\mathcal{A}_t}\left\lvert \frac{1}{N}\sum_{n=1}^N\left\langle \eta_n, \Phi(u_n;\alpha) \right\rangle_{\mathcal{Y}} \right\rvert \leq \frac{\left\lVert \eta_1 \right\rVert_{L^2_{\mathbb{P}}(\Omega;\mathcal{Y})}\left\lVert \varphi \right\rVert_{L^\infty}}{\sqrt{N}}\sqrt{t}\,.
    \end{equation}

Fix $t>0$ and $\delta\in(0,1)$. Define
    \begin{align}
        Z_t&\coloneqq \sup_{\alpha\in\mathcal{A}_t}\left\lvert \mathscr{R}_N(\alpha;\mathcal{G})-\mathscr{R}(\alpha;\mathcal{G}) \right\rvert\\
        &= \sup_{\alpha\in\mathcal{A}_t}\left\lvert \frac{1}{N}\sum_{n=1}^N\left\lVert \mathcal{G}(u_n)-\Phi(u_n;\alpha) \right\rVert_{\mathcal{Y}}^2 - \operatorname{\mathbb{E}}_{u\sim\nu}\left\lVert \mathcal{G}(u)-\Phi(u;\alpha) \right\rVert_{\mathcal{Y}}^2 \right\rvert\,,
    \end{align}
    where
    \begin{equation}
        \mathcal{A}_t\coloneqq {\left\{ \alpha\in\mathbb{R}^M \,\middle|\, \left\lVert \alpha \right\rVert_M^2\leq t \right\}}\,.
    \end{equation}
    If $N\geq\log(1/\delta)$, then conditioned on the realizations ${\{\theta_m\}}$ in the family $\Phi$, it holds that
    \begin{equation}
        Z_t\leq \operatorname{\mathbb{E}}_{{\{u_n\}}} [Z_t] + 32e^{3/2}(\left\lVert \mathcal{G} \right\rVert_{L_\nu^\infty}^2 + \left\lVert \varphi \right\rVert_{L^\infty}^2 t)\sqrt{\frac{\log(1/\delta)}{N}}
    \end{equation}
    with probability at least $1-\delta$.

Fix $t>0$. Define $Z_t$ as in Lem.~D.6. Conditioned on the realizations ${\{\theta_m\}}$ in the family $\Phi$, it holds that
    \begin{equation}
        \operatorname{\mathbb{E}}_{{\{u_n\}}} [Z_t] \leq \frac{4\left\lVert \mathcal{G} \right\rVert_{L_\nu^\infty}^2}{\sqrt{N}}
        + \frac{4\left\lVert \varphi \right\rVert_{L^\infty}^2}{\sqrt{N}}t\,.
    \end{equation}
